#!/bin/sh
aok_vfs_check(){ r=$(active_rootfs); out=$(aok_report_file vfs); for p in dev dev/pts proc sys run tmp var/run; do q=$r/$p; [ "$r" = / ] && q=/$p; printf '%-20s exists=%-3s mounted=%s\n' "$q" "$([ -e "$q" ] && echo yes || echo no)" "$(aok_mountpoint "$q" && echo yes || echo no)"; done >"$out"; grep -E 'noexec| ro[,)]' /proc/mounts >>"$out" 2>/dev/null || true; ui_text 'Virtual filesystem check' "$(cat "$out")"; }
aok_vfs_repair(){ r=$(active_rootfs); [ "$r" != / ] || return; aok_confirm "Repair virtual filesystem layout under $r?" || return; as_root mkdir -p "$r/dev/pts" "$r/proc" "$r/sys" "$r/run" "$r/tmp"; as_root chmod 1777 "$r/tmp"; [ -e "$r/var/run" ] || as_root ln -s /run "$r/var/run" 2>/dev/null || true; [ -e "$r/dev/ptmx" ] || as_root ln -s pts/ptmx "$r/dev/ptmx" 2>/dev/null || true; aok_chroot_mounts; }
aok_state_files(){ r=$(active_rootfs); find "$r" -maxdepth 5 -type f \( -name deploy_state -o -name '*build*state*' -o -name '*.lock' -o -name '*.pid' \) 2>/dev/null; }
aok_state_inspect(){ ui_text 'Build-state files' "$(aok_state_files | while read f; do echo "--- $f"; head -n 20 "$f" 2>/dev/null; done)"; }
aok_state_set(){ f=$(aok_state_files | head -n1); [ -n "$f" ] || { ui_msg State 'No state file found.'; return; }; val=$(ui_menu State 'Set build state' initialising initialising build build finalizing finalizing done done) || { _menu_rc=$?; [ "$_menu_rc" -eq "${UI_MENU_BACK_RC:-90}" ] && return 0; return "$_menu_rc"; }; backup_file "$f"; write_file "$f" 644 "$val"; }
aok_setup_run(){ r=$(active_rootfs); scripts=$(find "$r/opt/AOK" -maxdepth 3 -type f -name 'setup_*.sh' 2>/dev/null); [ -n "$scripts" ] || { ui_msg Setup 'No setup scripts found.'; return; }; set --; old=$IFS; IFS='\n'; for s in $scripts; do set -- "$@" "$s" "$(basename "$s")"; done; IFS=$old; s=$(ui_menu Setup 'Select setup script' "$@") || { _menu_rc=$?; [ "$_menu_rc" -eq "${UI_MENU_BACK_RC:-90}" ] && return 0; return "$_menu_rc"; }; aok_confirm "Run $s inside active rootfs?" || return; aok_chroot_mounts; run_capture Setup as_root chroot "$r" /bin/sh "${s#$r}"; }
aok_pkg_partial(){ r=$(active_rootfs); { [ -f "$r/var/lib/dpkg/status" ] && grep -B2 -A2 'Status:.*half-\|unpacked' "$r/var/lib/dpkg/status"; [ -d "$r/var/lib/apk" ] && ls -la "$r/var/lib/apk"; [ -d "$r/var/lib/pacman" ] && find "$r/var/lib/pacman" -name '*.part' -o -name '*.lock'; } >"$REPORT_DIR/aok-partial-packages.txt"; ui_text Packages "$(cat "$REPORT_DIR/aok-partial-packages.txt")"; }
aok_repair_menu(){ while :; do c=$(ui_menu 'AOK repair & recovery' "Active: $(active_rootfs)" vfscheck 'Validate virtual filesystems and mount flags' vfsrepair 'Repair virtual filesystems' resetmounts 'Reset leaked mounts' state 'Inspect build-state markers' setstate 'Change build state interactively' partial 'Detect partially installed packages' setup 'Run/resume distribution setup script' locks 'Find stale locks and PID files' cleanup 'Remove selected stale lock/PID file' recovery 'Open recovery shell' report 'Generate recovery report') || { _menu_rc=$?; [ "$_menu_rc" -eq "${UI_MENU_BACK_RC:-90}" ] && return 0; return "$_menu_rc"; }; case $c in vfscheck) aok_vfs_check;; vfsrepair) aok_vfs_repair;; resetmounts) aok_chroot_unmounts; aok_chroot_mounts;; state) aok_state_inspect;; setstate) aok_state_set;; partial) aok_pkg_partial;; setup) aok_setup_run;; locks) ui_text Locks "$(aok_state_files)";; cleanup) f=$(ui_input Cleanup 'Exact lock/PID file to remove:' '') || continue; case $f in "$(active_rootfs)"/*) aok_confirm "Remove $f?" && as_root rm -f "$f";; *) ui_msg Safety 'File must be inside active rootfs.';; esac;; recovery) aok_chroot_enter;; report) aok_vfs_check; aok_state_inspect;; esac; done; }
